package dev.musicstudio.song;

import dev.musicstudio.song.SongProject.*;
import dev.musicstudio.blueprint.BlueprintData;
import dev.musicstudio.media.AudioFiles;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class ReorderTest {
    private static final int BAR=4*SongProject.PPQ;
    private SongProject song(){
        var s=new SongProject();s.schemaVersion=2;s.endPpq=4*BAR;s.loop=false;
        for(int c=0;c<3;c++){var source=new Channel("Source "+c,"minecraft:block.note_block."+List.of("harp","bell","bass").get(c),0x556677+c);source.muted=c==1;s.channels.add(source);var t=new Track("Lane "+c,0x667788+c);t.displayHeight=45+c*25;t.muted=c==1;s.tracks.add(t);}
        for(int pi=0;pi<3;pi++){var p=new Pattern("Pattern "+pi,3);for(int c=0;c<3;c++)p.notes.get(c).add(new Note(pi*4+c,1,66+c,127));s.patterns.add(p);s.clips.add(Clip.pattern(pi,pi,pi*BAR,BAR));}
        for(int a=0;a<2;a++){String id=(a==0?"a":"b").repeat(64);s.assets.add(new Asset(id,"Audio "+a,id+"-source.wav",44100));var audio=new Channel("Recording "+a,"musicstudio:sample/"+id,0x778899+a);audio.sampleId=id;audio.tunable=false;s.audioSources.add(audio);s.clips.add(Clip.audio(a==0?0:2,a,(3-a*2)*BAR,SongProject.PPQ));}
        s.validate();return s;
    }
    private List<String> events(SongProject s,int pattern,boolean only,int subtract){return s.events(pattern,only).stream().map(e->s.voice(e.channel()).id+":"+(e.track()<0?"":s.tracks.get(e.track()).id)+":"+(e.start()-subtract)+":"+e.duration()+":"+e.pitch()+":"+e.velocity()+":"+e.offset()).sorted().toList();}
    private Map<String,String> clips(SongProject s){var map=new TreeMap<String,String>();for(var c:s.clips)map.put(c.id,(s.schemaVersion==1?s.channels.get(c.channel).id:s.tracks.get(c.track).id)+":"+(c.audio()?s.audioSources.get(c.audioSource).id:s.patterns.get(c.pattern).id)+":"+c.start+":"+c.duration+":"+c.contentOffset+":"+c.contentLength);return map;}
    private Map<String,List<String>> phrases(SongProject s){var map=new TreeMap<String,List<String>>();for(int i=0;i<s.patterns.size();i++)map.put(s.patterns.get(i).id,events(s,i,true,0));return map;}
    @Test void patternMovePreservesEveryClipAndAllMusicalContent(){var s=song();var refs=clips(s);var notes=phrases(s);var score=events(s,0,false,0);String id=s.patterns.get(2).id;s.reorderPattern(2,0);assertEquals(id,s.patterns.getFirst().id);assertEquals(refs,clips(s));assertEquals(notes,phrases(s));assertEquals(score,events(s,0,false,0));s.validate();}
    @Test void trackMoveCarriesPatternAndAudioClipsAndKeepsTrackSettings(){var s=song();var refs=clips(s);var score=events(s,0,false,0);var moved=s.tracks.getFirst();s.reorderTrack(0,2);assertSame(moved,s.tracks.get(2));assertEquals(45,s.tracks.get(2).displayHeight);assertTrue(s.tracks.getFirst().muted);assertEquals(refs,clips(s));assertEquals(score,events(s,0,false,0));s.validate();}
    @Test void channelMoveReordersTheMatchingVoiceInEveryPattern(){var s=song();var refs=clips(s);var notes=phrases(s);var score=events(s,0,false,0);String id=s.channels.getFirst().id;var noteIds=s.patterns.stream().map(p->p.notes.getFirst().getFirst().id).toList();s.reorderChannel(0,2);assertEquals(id,s.channels.get(2).id);for(int p=0;p<3;p++)assertEquals(noteIds.get(p),s.patterns.get(p).notes.get(2).getFirst().id);assertEquals(refs,clips(s));assertEquals(notes,phrases(s));assertEquals(score,events(s,0,false,0));s.validate();}
    @Test void independentAudioMovePreservesAudioReferencesAndSound(){var s=song();var refs=clips(s);var score=events(s,0,false,0);var a=s.audioSources.getFirst();s.reorderAudioSource(0,1);assertSame(a,s.audioSources.get(1));assertEquals(refs,clips(s));assertEquals(score,events(s,0,false,0));s.validate();}
    @Test void legacySingleSourceClipsAlsoKeepTheirSoundBinding(){var s=SongProject.legacyDemo();var refs=clips(s);var score=events(s,0,false,0);var notes=phrases(s);s.reorderChannel(0,7);s.reorderPattern(1,0);assertEquals(refs,clips(s));assertEquals(score,events(s,0,false,0));assertEquals(notes,phrases(s));s.validate();}
    @Test void clipboardKeepsStableTrackPatternAndAudioIdsAfterEveryListMoves(){var s=song();var selected=new LinkedHashSet<String>();s.clips.forEach(c->selected.add(c.id));var clipboard=EditorClipboard.copyClips(s,selected);var before=events(s,0,false,0);s.reorderPattern(0,2);s.reorderChannel(2,0);s.reorderTrack(0,2);s.reorderAudioSource(0,1);s.endPpq=8*BAR;var ids=clipboard.pasteClips(s,4*BAR);assertEquals(5,ids.size());var pasted=ProjectStore.copy(s);pasted.clips.removeIf(c->!ids.contains(c.id));assertEquals(before,events(pasted,0,false,4*BAR));s.validate();}
    @Test void clipboardRecreatesDeletedPatternWithNotesBoundToReorderedSources(){var s=song();var selected=s.clips.getFirst();var p=s.patterns.getFirst();var expected=events(s,0,true,0);var clipboard=EditorClipboard.copyClips(s,Set.of(selected.id));s.removePattern(0);s.reorderChannel(0,2);s.endPpq=8*BAR;clipboard.pasteClips(s,4*BAR);int index=0;while(!s.patterns.get(index).id.equals(p.id))index++;assertEquals(expected,events(s,index,true,0));s.validate();}
    @Test void roundTripAndInverseMovesKeepTheProjectPortableAndExact(){var s=song();String before=ProjectStore.encode(s);s.reorderPattern(0,2);s.reorderTrack(2,0);s.reorderChannel(1,0);s.reorderAudioSource(0,1);var loaded=BlueprintData.unpack(BlueprintData.pack(s));assertEquals(ProjectStore.encode(s),ProjectStore.encode(loaded));loaded.reorderAudioSource(1,0);loaded.reorderChannel(0,1);loaded.reorderTrack(0,2);loaded.reorderPattern(2,0);assertEquals(before,ProjectStore.encode(loaded));}
    @Test void noOpAndInvalidDropsAreAtomic(){var s=song();String before=ProjectStore.encode(s);s.reorderPattern(1,1);s.reorderTrack(0,0);s.reorderChannel(2,2);s.reorderAudioSource(1,1);assertEquals(before,ProjectStore.encode(s));assertThrows(StudioException.class,()->s.reorderPattern(-1,0));assertThrows(StudioException.class,()->s.reorderChannel(0,3));assertThrows(StudioException.class,()->s.reorderTrack(3,0));assertThrows(StudioException.class,()->s.reorderAudioSource(0,2));assertEquals(before,ProjectStore.encode(s));}
    @Test void realPcmMixIsUnchangedByReordering(){var s=song();Map<String,AudioFiles.Source> waves=new HashMap<>();int i=0;for(var c:s.voices()){float[] pcm=new float[4410];int frequency=220+i++*50;for(int n=0;n<pcm.length;n++)pcm[n]=(float)(.1*Math.sin(2*Math.PI*frequency*n/44100));waves.put(c.id,new AudioFiles.Source(new AudioFiles.Wave(pcm,pcm.clone()),1,1));}assertDoesNotThrow(()->{var before=AudioFiles.mixFullExport(s,c->waves.get(c.id));s.reorderPattern(0,2);s.reorderTrack(0,2);s.reorderChannel(0,2);s.reorderAudioSource(0,1);var after=AudioFiles.mixFullExport(s,c->waves.get(c.id));assertArrayEquals(before.wave().left(),after.wave().left(),.000001f);assertArrayEquals(before.wave().right(),after.wave().right(),.000001f);});}
}
